const upsertDirectoryProfile = `-- name: UpsertDirectoryProfile :exec
INSERT INTO organization.directory_profiles (organization_id, user_id, connection_id, profile)
VALUES ($1, $2, $3, jsonb_strip_nulls($4::jsonb))
ON CONFLICT (organization_id, user_id, connection_id) DO UPDATE
SET profile = jsonb_strip_nulls(directory_profiles.profile || $4::jsonb), updated_at = NOW()
`

type UpsertDirectoryProfileParams struct {
	OrganizationID uuid.UUID
	UserID         uuid.UUID
	ConnectionID   string
	Profile        []byte
}

// Merges profile into what the connection set on the person before; a null
// field removes one.
func (q *Queries) UpsertDirectoryProfile(ctx context.Context, arg UpsertDirectoryProfileParams) error {
	_, err := q.db.Exec(ctx, upsertDirectoryProfile,
		arg.OrganizationID,
		arg.UserID,
		arg.ConnectionID,
		arg.Profile,
	)
	return err
}
